class Solution {
public:
    vector<vector<int>> multiply(vector<vector<int>>& mat1, vector<vector<int>>& mat2) {
        int m = mat1.size(), k = mat1[0].size(), n = mat2[0].size();
        vector<vector<int>> res(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int p = 0; p < k; ++p) {
                if (mat1[i][p] != 0) {
                    for (int j = 0; j < n; ++j) {
                        res[i][j] += mat1[i][p] * mat2[p][j];
                    }
                }
            }
        }
        return res;
    }
};

class Solution {
    public int[][] multiply(int[][] mat1, int[][] mat2) {
        int m = mat1.length, k = mat1[0].length, n = mat2[0].length;
        int[][] res = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int p = 0; p < k; p++) {
                if (mat1[i][p] != 0) {
                    for (int j = 0; j < n; j++) {
                        res[i][j] += mat1[i][p] * mat2[p][j];
                    }
                }
            }
        }
        return res;
    }
}

/**
 * @param {number[][]} mat1
 * @param {number[][]} mat2
 * @return {number[][]}
 */
var multiply = function(mat1, mat2) {
    const m = mat1.length, k = mat1[0].length, n = mat2[0].length;
    const res = Array.from({ length: m }, () => new Array(n).fill(0));
    for (let i = 0; i < m; i++) {
        for (let p = 0; p < k; p++) {
            if (mat1[i][p] !== 0) {
                for (let j = 0; j < n; j++) {
                    res[i][j] += mat1[i][p] * mat2[p][j];
                }
            }
        }
    }
    return res;
};
